describe('Table Sorting by Column Headers', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should sort table by clicking column headers in ascending order', () => {
    // Verify initial table state
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Click the first column header to sort by Name
    cy.get('[data-testid="table-header-name"]').click();
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Verify table is now sorted by Name in ascending order
    cy.get('[data-testid="table-row"]').first().should('contain', 'Alice');
    cy.get('[data-testid="table-row"]').last().should('contain', 'Zoe');

    // Click the same column header again to toggle sort order
    cy.get('[data-testid="table-header-name"]').click();
    cy.get('[data-testid="table-row"]').first().should('contain', 'Zoe');
    cy.get('[data-testid="table-row"]').last().should('contain', 'Alice');
  });

  it('should sort table by clicking column headers in descending order', () => {
    // Verify initial table state
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Click the first column header to sort by Name in ascending order
    cy.get('[data-testid="table-header-name"]').click();
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Verify table is now sorted by Name in ascending order
    cy.get('[data-testid="table-row"]').first().should('contain', 'Alice');
    cy.get('[data-testid="table-row"]').last().should('contain', 'Zoe');

    // Click the same column header again to toggle sort order to descending
    cy.get('[data-testid="table-header-name"]').click();
    cy.get('[data-testid="table-row"]').first().should('contain', 'Zoe');
    cy.get('[data-testid="table-row"]').last().should('contain', 'Alice');

    // Verify table is now sorted by Name in descending order
    cy.get('[data-testid="table-row"]').first().should('contain', 'Zoe');
    cy.get('[data-testid="table-row"]').last().should('contain', 'Alice');
  });
});
